//! Compatibility tests against fixtures generated by the Go implementation.

use std::collections::BTreeMap;

use pm_profile::{
    derive_profile_id, match_fingerprints, parse_fingerprints, Fingerprint, MatchingData, Profile,
    Tag,
};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/profile.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn fingerprints(value: &Value) -> Vec<Fingerprint> {
    if value.is_null() {
        return Vec::new();
    }
    serde_json::from_value(value.clone()).unwrap()
}

struct TestData {
    tags: Vec<Tag>,
    env: BTreeMap<String, String>,
    path: String,
    matching_path: String,
    cmdline: String,
}

impl MatchingData for TestData {
    fn tags(&self) -> &[Tag] {
        &self.tags
    }

    fn env(&self) -> &BTreeMap<String, String> {
        &self.env
    }

    fn path(&self) -> &str {
        &self.path
    }

    fn matching_path(&self) -> &str {
        &self.matching_path
    }

    fn cmdline(&self) -> &str {
        &self.cmdline
    }
}

fn string_field(value: &Value, name: &str) -> String {
    value
        .get(name)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string()
}

#[test]
fn profile_json_matches_go() {
    let fixture = fixture();
    let expected = fixture["profile"].as_str().unwrap();

    let mut profile = Profile {
        id: "test-profile-id".to_string(),
        source: "local".to_string(),
        name: "Test Profile".to_string(),
        description: "A profile for fixtures.".to_string(),
        warning: "Be careful.".to_string(),
        warning_last_updated: 1_700_000_200,
        homepage: "https://example.com".to_string(),
        icon: "/tmp/icon.png".to_string(),
        icon_type: "path".to_string(),
        icons: vec![
            pm_profile::Icon::new("api", "/api/v1/icons/1", "core"),
            pm_profile::Icon::new("path", "/tmp/icon.png", "user"),
        ],
        linked_path: "/usr/bin/test".to_string(),
        presentation_path: "/usr/bin/test".to_string(),
        use_presentation_path: true,
        fingerprints: vec![
            Fingerprint::new("path", "", "equals", "/usr/bin/test"),
            Fingerprint::new("tag", "app-image-path", "prefix", "/tmp/.mount_")
                .with_merged_from("local/other"),
        ],
        ..Profile::default()
    };
    // Go sorts map keys when marshalling; build the config in that order.
    let filter = serde_json::json!({
        "defaultAction": "block",
        "endpoints": ["+ 1.1.1.1:443", "- 10.0.0.0/8"],
        "lists": ["list-a"],
    });
    profile.config.insert("filter".to_string(), filter.clone());
    profile.last_edited = 1_700_000_100;
    profile.created = 1_700_000_000;

    let serialized = String::from_utf8(pm_dsd::gojson::to_vec(&profile).unwrap()).unwrap();
    assert_eq!(serialized, expected);

    // The parsed config exposes the settings.
    let (config, error) = profile.parse_config();
    assert!(error.is_none());
    assert_eq!(config.default_action, pm_profile::DEFAULT_ACTION_BLOCK);
    assert_eq!(config.endpoints, vec!["+ 1.1.1.1:443", "- 10.0.0.0/8"]);
    assert_eq!(config.filter_lists, vec!["list-a"]);

    // Round trip through serde.
    let decoded: Profile = serde_json::from_str(expected).unwrap();
    assert_eq!(decoded.warning_last_updated, 1_700_000_200);
    let reserialized = String::from_utf8(pm_dsd::gojson::to_vec(&decoded).unwrap()).unwrap();
    assert_eq!(reserialized, expected);
}

#[test]
fn fingerprint_matching_matches_go() {
    let fixture = fixture();
    let cases = fixture["match_cases"].as_array().unwrap();
    assert!(!cases.is_empty());

    for case in cases {
        let name = case["name"].as_str().unwrap();
        let fps = fingerprints(&case["fingerprints"]);
        let (parsed, error) = parse_fingerprints(&fps, &string_field(case, "linked_path"));

        match case.get("error").and_then(Value::as_str) {
            Some(expected_error) => {
                assert_eq!(error.as_deref(), Some(expected_error), "error of {name}");
            }
            None => assert!(error.is_none(), "unexpected error in {name}: {error:?}"),
        }

        let tags: Vec<Tag> = case
            .get("tags")
            .map(|tags| serde_json::from_value(tags.clone()).unwrap())
            .unwrap_or_default();
        let env: BTreeMap<String, String> = case
            .get("env")
            .map(|env| serde_json::from_value(env.clone()).unwrap())
            .unwrap_or_default();
        let data = TestData {
            tags,
            env,
            path: string_field(case, "path"),
            matching_path: string_field(case, "matching_path"),
            cmdline: string_field(case, "cmdline"),
        };

        let score = match_fingerprints(&parsed, &data);
        assert_eq!(
            score,
            case["score"].as_i64().unwrap() as i32,
            "score of {name}"
        );
    }
}

#[test]
fn derived_profile_ids_match_go() {
    let fixture = fixture();
    let cases = fixture["id_cases"].as_array().unwrap();
    assert!(!cases.is_empty());

    for case in cases {
        let name = case["name"].as_str().unwrap();
        let mut fps = fingerprints(&case["fingerprints"]);
        let derived = derive_profile_id(&mut fps);
        assert_eq!(derived, case["id"].as_str().unwrap(), "ID of {name}");
    }
}
